def find_minimal_edit(s_in, s_out):
    """Find the minimal edit that transforms s_in to s_out"""
    # Simple implementation to find first differing position and what needs to change
    min_len = min(len(s_in), len(s_out))
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            # Found a difference
            old_char = s_in[i]
            new_char = s_out[i]
            return (old_char, new_char, i)

    # If we get here, strings are different lengths
    if len(s_in) < len(s_out):
        # Insertion at the end
        return ("", s_out[len(s_in):], len(s_in))
    elif len(s_in) > len(s_out):
        # Deletion at the end
        return (s_in[len(s_out):], "", len(s_out))
    else:
        return ("", "", -1)  # No difference

def propose_rule_candidates(s_in, s_out):
    """Propose rule candidates from a transformation"""
    # For simplicity, let's propose simple replacements
    # Most specific: exact character replacement
    # General: substring replacement

    old_sub, new_sub, pos = find_minimal_edit(s_in, s_out)

    candidates = []

    # Specific candidate: exact replacement at position
    if old_sub and new_sub:
        candidates.append((old_sub, new_sub))

    # General candidates based on patterns
    if len(s_in) > 1 and len(s_out) > 1:
        # Try replacing substrings
        if len(s_in) <= 3 and len(s_out) <= 3:
            candidates.append((s_in, s_out))

    # Add more general candidates
    if len(s_out) > len(s_in):
        # Something was added
        if len(s_out) - len(s_in) == 4 and s_out[:4] == "vbcx":
            candidates.append(("g", "gvbcx"))  # Special case
        elif len(s_out) - len(s_in) == 4 and s_out[:4] == "fvbcx":
            candidates.append(("b", "fvbcx"))

    # Remove duplicates and sort by specificity 
    unique_candidates = []
    seen = set()
    for cand in candidates:
        if cand not in seen:
            seen.add(cand)
            unique_candidates.append(cand)

    return unique_candidates

